export function captionComparisonKey(value){
 return String(value??'').normalize('NFKC').toLocaleLowerCase('en-US')
  .replace(/\b(psalms?|matthew|mark|luke|john|acts|romans|philippians|thessalonians|corinthians|timothy|peter|hebrews|revelation|genesis|exodus|proverbs|isaiah|james|ephesians|colossians|galatians)\s+(\d+)\s*:\s*(\d+)(?:\s*[-–—]\s*(\d+))?/gi, (_,book,chapter,verse,end)=>`${book==='psalm'?'psalms':book} ${chapter}:${verse}${end?`–${end}`:''}`)
  .replace(/[\u200B-\u200D\uFEFF]/g,'').replace(/[‘’`]/g,"'").replace(/[“”]/g,'"')
  .replace(/(?<=\d),(?=\d{3}(?:\D|$))/g,'')
  .replace(/^[\s"'“”‘’([{]+|[\s"'“”‘’)\]},.!?;:，。！？；：]+$/gu,'')
  .replace(/\s+/gu,' ').trim();
}
